#!/usr/bin/env node
// Keeps the Claude Code agents in .claude/agents/ in sync with the shared agents in .github/agents/.
//
// .github/agents/<name>.agent.md is the source of truth: GitHub Copilot reads it, and the AI
// pipeline (scripts/pipeline and its stages) builds its prompts from it. Each one is rendered to .claude/agents/<name>.md
// so the same agent can be run from Claude Code. Claude-only frontmatter (tools, isolation, ...)
// comes from scripts/agents-claude.json.
//
// An agent written directly in .claude/agents/ (no "Generated by" marker) is adopted: its name,
// description and body are copied to .github/agents/<name>.agent.md, any other frontmatter keys are
// moved into scripts/agents-claude.json, and the Claude file is then regenerated from the source.
//
// Usage: node scripts/sync-agents.mjs           write changes
//        node scripts/sync-agents.mjs --check   exit 1 if anything is out of sync (CI)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const githubDir = path.join(root, '.github', 'agents');
const claudeDir = path.join(root, '.claude', 'agents');
const lessonsDir = path.join(githubDir, 'lessons');
const overridesFile = path.join(root, 'scripts', 'agents-claude.json');
const MARKER = '# Generated by scripts/sync-agents.mjs';
const check = process.argv.includes('--check');

const rel = (p) => path.relative(root, p);
const readOverrides = () => (fs.existsSync(overridesFile) ? JSON.parse(fs.readFileSync(overridesFile, 'utf8')) : {});

function parse(text) {
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(text);
  if (!m) return { data: {}, body: text };
  const data = {};
  for (const line of m[1].split(/\r?\n/)) {
    const kv = /^([A-Za-z][A-Za-z0-9_-]*):\s*(.*)$/.exec(line);
    if (!kv) continue;
    let v = kv[2].trim();
    if (/^".*"$/.test(v)) v = JSON.parse(v);
    else if (/^'.*'$/.test(v)) v = v.slice(1, -1).replace(/''/g, "'");
    data[kv[1]] = v;
  }
  return { data, body: text.slice(m[0].length) };
}

const yamlValue = (v) => (Array.isArray(v) ? v.join(', ') : typeof v === 'string' && /[:#'"\[\]{}]|^\s|\s$/.test(v) ? JSON.stringify(v) : String(v));

function renderClaude(name, source, overrides) {
  const { data, body } = parse(source);
  if (data.name && data.name !== name) throw new Error(`.github/agents/${name}.agent.md has name: ${data.name}; it must match the file name`);
  const front = [
    '---',
    `${MARKER} from .github/agents/${name}.agent.md.`,
    '# Do not edit: change the source and run `npm run agents:sync`.',
    `name: ${name}`,
    `description: ${yamlValue(data.description ?? '')}`,
  ];
  for (const [k, v] of Object.entries(overrides[name] ?? {})) front.push(`${k}: ${yamlValue(v)}`);
  front.push('---', '');
  const lessons = [
    '',
    '## Lessons',
    '',
    `If \`.github/agents/lessons/${name}.md\` exists, read it before you start and follow every rule in it. They come from earlier verifier denials. (When the QE pipeline runs this agent it already includes them.)`,
    '',
  ];
  return front.join('\n') + '\n' + body.trim() + '\n' + lessons.join('\n');
}

const problems = [];
const writes = [];
const overrides = readOverrides();
let overridesChanged = false;

fs.mkdirSync(claudeDir, { recursive: true });
const sources = new Set(fs.readdirSync(githubDir).filter((f) => f.endsWith('.agent.md')).map((f) => f.slice(0, -'.agent.md'.length)));

// Adopt agents authored directly in .claude/agents/.
for (const f of fs.readdirSync(claudeDir).filter((f) => f.endsWith('.md'))) {
  const name = f.slice(0, -3);
  const file = path.join(claudeDir, f);
  const text = fs.readFileSync(file, 'utf8');
  if (text.includes(MARKER)) {
    if (!sources.has(name)) {
      problems.push(`${rel(file)} is generated but .github/agents/${name}.agent.md no longer exists`);
      writes.push({ file, content: null });
    }
    continue;
  }
  if (sources.has(name)) {
    problems.push(`${rel(file)} was edited by hand; edit .github/agents/${name}.agent.md instead (this run regenerates it)`);
    continue;
  }
  problems.push(`${rel(file)} is a new Claude agent; adopting it into .github/agents/${name}.agent.md`);
  const { data, body } = parse(text);
  const extra = Object.fromEntries(Object.entries(data).filter(([k]) => !['name', 'description'].includes(k)));
  if (Object.keys(extra).length) {
    overrides[name] = { ...(overrides[name] ?? {}), ...extra };
    overridesChanged = true;
  }
  const source = ['---', `name: ${name}`, `description: ${yamlValue(data.description ?? '')}`, '---', '', ''].join('\n') + body.trimStart();
  writes.push({ file: path.join(githubDir, `${name}.agent.md`), content: source });
  sources.add(name);
}

for (const name of [...sources].sort()) {
  const srcFile = path.join(githubDir, `${name}.agent.md`);
  const pending = writes.find((w) => w.file === srcFile);
  const source = pending ? pending.content : fs.readFileSync(srcFile, 'utf8');
  const target = path.join(claudeDir, `${name}.md`);
  const want = renderClaude(name, source, overrides);
  const have = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null;
  if (have !== want) {
    if (have !== null && have.includes(MARKER)) problems.push(`${rel(target)} is out of date`);
    else if (have === null) problems.push(`${rel(target)} is missing`);
    writes.push({ file: target, content: want });
  }
}

for (const name of Object.keys(overrides)) {
  if (!sources.has(name)) problems.push(`scripts/agents-claude.json has settings for unknown agent "${name}"`);
}

if (check) {
  if (problems.length) {
    console.error('Agents are out of sync:\n' + problems.map((p) => `  - ${p}`).join('\n') + '\nRun: npm run agents:sync');
    process.exit(1);
  }
  console.log(`agents in sync (${sources.size})`);
  process.exit(0);
}

for (const p of problems) console.log(`- ${p}`);
for (const { file, content } of writes) {
  if (content === null) fs.rmSync(file);
  else fs.writeFileSync(file, content);
  console.log(`${content === null ? 'removed' : 'wrote'} ${rel(file)}`);
}
if (overridesChanged) {
  fs.writeFileSync(overridesFile, JSON.stringify(overrides, null, 2) + '\n');
  console.log(`wrote ${rel(overridesFile)}`);
}
if (!writes.length && !overridesChanged) console.log(`agents in sync (${sources.size})`);
